"""Cuaderno del estudiante, 8.º básico Lengua y Literatura, OA 19 (modos verbales y efecto persuasivo)."""
from __future__ import annotations

from student_content_le8_c import E, L, MAT

OA19 = "LE08 OA 19"

L(OA19, 1,
  MAT,
  "Aprenderé a reconocer los tres modos verbales (indicativo, subjuntivo e imperativo) en oraciones y textos, y a explicar qué expresan.",
  ["Reconozco el verbo conjugado.", "Distingo pasado, presente y futuro."],
  ["El modo verbal indica la actitud de quien habla frente a lo que dice. El indicativo presenta hechos como reales o seguros: «Los estudiantes leen en silencio», «El tren llegó a las 8». El subjuntivo expresa deseo, duda, posibilidad o hipótesis: «Ojalá llueva», «Quizás venga mi tío», «Espero que sea cierto». El imperativo expresa órdenes, ruegos o consejos: «Cierra la puerta», «Siéntense».",
   "Cada modo tiene sus propias formas. En indicativo: canta, cantó, cantará. En subjuntivo: cante, cantara (o cantase). En imperativo, el tú usa «canta», el usted usa «cante», el nosotros usa «cantemos» y el ustedes usa «canten». Cuando la orden es negativa, se usan las formas del subjuntivo: «No corras», «No hables fuerte».",
   "Para identificar el modo, mira el contexto: ¿afirma un hecho?, ¿expresa un deseo o una duda?, ¿da una orden? A menudo hay palabras que anuncian el subjuntivo: ojalá, quizás, tal vez, es posible que, espero que, dudo que. Reconocer el modo ayuda a leer mejor y, más adelante, a escribir con un efecto elegido."],
  [("modo verbal", "actitud de quien habla frente a lo que dice: indicativo, subjuntivo o imperativo"), ("indicativo", "modo que presenta hechos como reales o seguros"), ("subjuntivo", "modo que expresa deseo, duda, posibilidad o hipótesis"), ("imperativo", "modo que expresa órdenes, ruegos o consejos")],
  [("Identificar el modo", "¿En qué modo está «sea» en «Espero que sea cierto»?",
    ["«Espero que» expresa deseo.", "El verbo «sea» no afirma un hecho, sino una posibilidad deseada.", "Es subjuntivo."],
    "Subjuntivo"),
   ("Orden negativa", "¿Qué forma tiene «hables» en «No hables fuerte»?",
    ["Es una orden.", "Pero el imperativo negativo no tiene forma propia.", "Usa la forma del subjuntivo."],
    "Forma del subjuntivo con valor de orden")],
  [("Creer que toda oración con «espero» está en indicativo.", "Se ve el primer verbo y se ignora el segundo.", "Mira cada verbo: «espero» es indicativo, «sea» es subjuntivo."),
   ("Creer que «No corras» es indicativo.", "Se olvida que la orden negativa toma la forma del subjuntivo.", "Una orden negativa usa subjuntivo.")],
  ([E("¿Qué modo tiene «Los estudiantes leen en silencio»: indicativo o subjuntivo?", "Indicativo", "Presenta un hecho real."),
    E("¿Qué modo expresa «Ojalá llueva mañana»?", "Subjuntivo", "Expresa un deseo."),
    E("¿Qué modo tiene «Guarda silencio»?", "Imperativo", "Es una orden dirigida a una persona.")],
   [E("¿En qué modo está «sea» en «Espero que sea cierto»?", "Subjuntivo", "Expresa algo deseado, no confirmado."),
    E("¿«Cierra la puerta» expresa una orden o un hecho?", "Una orden", "Es una forma del imperativo."),
    E("¿«El tren llegó a las 8» está en indicativo o en subjuntivo?", "Indicativo", "Informa un hecho ocurrido.")],
   [E("¿Qué modo tiene «venga» en «Quizás venga mi tío»?", "Subjuntivo", "«Quizás» introduce una posibilidad."),
    E("Completa con el verbo en subjuntivo: «Es importante que todos (llegar) puntuales».", "lleguen", "Después de «es importante que» se usa subjuntivo."),
    E("¿Cuántos verbos en imperativo hay en «Ven, siéntate y come»?", "3", "Son ven, siéntate y come, tres órdenes.")],
   [E("En «Pide que lo ayuden», ¿cuál verbo está en subjuntivo?", "Ayuden", "«Pide» es imperativo o indicativo; «ayuden» expresa lo que se pide."),
    E("¿Cuál frase expresa un hecho cierto: «Es posible que gane» o «Ganó la carrera»?", "Ganó la carrera", "El indicativo presenta el hecho como real.")],
   [E("¿Qué forma verbal tiene «no cruces» en «No cruces con luz roja»: la del imperativo afirmativo o la del subjuntivo?", "La del subjuntivo", "La orden negativa toma esa forma."),
    E("En «Si fuera más alto, jugaría básquetbol», ¿en qué modo está «fuera»?", "Subjuntivo", "Expresa una hipótesis que no es real.")]),
  [E("Un cartel dice: «Se prohíbe pasar. Mantenga la calma. Ojalá pronto reabran la sala». ¿En qué modo está «reabran»?", "Subjuntivo", "«Ojalá» expresa deseo.")],
  [E("¿Qué modo expresa deseo o duda?", "Subjuntivo", "Expresa lo que no es seguro."),
   E("¿Qué modo presenta hechos como reales?", "Indicativo", "Afirma lo seguro."),
   E("¿Qué modo expresa órdenes, ruegos o consejos?", "Imperativo", "Se usa para pedir que alguien actúe.")],
  ("Lee este texto de ejemplo: «Hoy practicamos para la feria. Ojalá el público disfrute la obra. Aprendan bien sus líneas y no lleguen tarde. Es posible que haya lluvia, pero actuaremos igual». 1) Subraya con un color los verbos en indicativo, con otro los de subjuntivo y con otro los de imperativo. 2) Escribe cuántos hay de cada modo. 3) Agrega una oración nueva con un verbo en cada modo.",
   "Indicativo: practicamos, actuaremos. Subjuntivo: disfrute, lleguen (orden negativa), haya. Imperativo: aprendan. Nueva oración: «Estudio mucho (indicativo), ojalá apruebe (subjuntivo); y tú, estudia también (imperativo)».",
   ["identifica cada modo", "reconoce la orden negativa como subjuntivo", "forma una oración con los tres modos"], ["verbos subrayados", "conteo", "oración nueva"], ["tomar «lleguen» como indicativo", "no justificar el modo"], "Pide a otra persona que revise tu clasificación y justifique en cada caso."),
  "Escribe un mensaje breve para un compañero que incluya un deseo, una orden y un hecho, y rotula los modos.",
  "Busca en un texto de tu casa tres verbos en cada modo y escribe qué expresa cada uno.")

L(OA19, 2,
  MAT,
  "Aprenderé a comparar cómo el indicativo y el subjuntivo expresan certeza o posibilidad, y a elegir cuál conviene según cuánta seguridad quiero transmitir.",
  ["Reconozco los tres modos verbales.", "Sé qué es el subjuntivo."],
  ["Cuando estamos seguros de algo usamos el indicativo: «Estoy seguro de que mañana hará frío», «Es evidente que el agua es esencial». Cuando dudamos o solo vemos una posibilidad, usamos el subjuntivo: «Tal vez mañana llueva», «Dudo que venga», «Es probable que lleguemos tarde».",
   "Algunas expresiones piden un modo fijo. Piden indicativo: creo que, sé que, es evidente que, estoy seguro de que. Piden subjuntivo: no creo que, dudo que, tal vez, quizás, es posible que, es probable que, ojalá. El mismo hecho cambia de fuerza según el modo: «Creo que llueve» afirma; «No creo que llueva» niega o duda. Con «tal vez» y «quizás» se admiten los dos modos, pero en este cuaderno usaremos el subjuntivo, que deja clara la duda.",
   "En un texto persuasivo, la elección del modo influye en el lector. El indicativo suena contundente: «El plástico contamina el mar». El subjuntivo suaviza o abre una duda: «Es posible que el plástico contamine el mar». Por eso, cuando quieres convencer con un dato firme, usa indicativo; cuando quieres reconocer un límite o una posibilidad, usa subjuntivo."],
  [("certeza", "seguridad total sobre algo"), ("posibilidad", "algo que puede ocurrir, pero no es seguro"), ("contundente", "que suena firme y convincente"), ("atenuar", "hacer menos fuerte lo que se dice")],
  [("Elegir el modo según la seguridad", "Completa: «Es evidente que el agua (ser) esencial».",
    ["«Es evidente que» expresa certeza.", "La certeza pide indicativo.", "El verbo queda en presente del indicativo: es."],
    "es"),
   ("Expresar duda", "Reescribe «Mañana lloverá» para expresar duda con «tal vez».",
    ["«Tal vez» pide subjuntivo.", "El verbo «llover» en presente del subjuntivo es «llueva».", "Escribo: Tal vez mañana llueva."],
    "Tal vez mañana llueva.")],
  [("Usar indicativo con «dudo que» o «no creo que».", "Se piensa que la duda puede ir con cualquier modo.", "Con «dudo que» y «no creo que» usa subjuntivo."),
   ("Usar subjuntivo con «es evidente que».", "Se mezcla certeza con duda.", "Después de expresiones de certeza, usa indicativo.")],
  ([E("¿«Creo que llueve» usa indicativo o subjuntivo en «llueve»?", "Indicativo", "«Creo que» expresa certeza."),
    E("¿«No creo que llueva» usa indicativo o subjuntivo en «llueva»?", "Subjuntivo", "«No creo que» expresa duda."),
    E("Entre «Estoy seguro de que viene» y «Dudo que venga», ¿cuál expresa duda?", "Dudo que venga", "«Dudo» introduce el subjuntivo.")],
   [E("¿«Es probable que lleguemos tarde» expresa certeza o posibilidad?", "Posibilidad", "Usa «es probable que» y subjuntivo."),
    E("¿«Sé que Ana ganó» expresa certeza o duda?", "Certeza", "«Sé que» afirma con seguridad."),
    E("¿Qué cambia entre «Es seguro que vendrá» y «Es posible que venga»?", "El grado de certeza", "El primero es seguro; el segundo, solo posible.")],
   [E("Completa con el verbo en el modo correcto: «Estoy seguro de que mañana (hacer) frío».", "hará", "«Estoy seguro de que» pide indicativo."),
    E("Completa con el verbo en el modo correcto: «Tal vez mañana (llover)».", "llueva", "«Tal vez» pide subjuntivo."),
    E("Completa con el verbo en el modo correcto: «Es evidente que la sequía (afectar) al campo».", "afecta", "Después de «es evidente que» va indicativo.")],
   [E("¿Qué versión transmite más certeza: «El plástico contamina el mar» o «Es posible que el plástico contamine el mar»?", "El plástico contamina el mar", "Está en indicativo y afirma un hecho."),
    E("¿Qué versión atenúa lo dicho: «Los precios subirán» o «Quizás los precios suban»?", "Quizás los precios suban", "El subjuntivo con «quizás» abre una duda.")],
   [E("Reescribe con duda usando «es posible que»: «Mañana habrá paro».", "Es posible que mañana haya paro.", "«Es posible que» pide subjuntivo: haya."),
    E("Reescribe con certeza usando «es evidente que»: «Quizás el agua sea escasa».", "Es evidente que el agua es escasa.", "«Es evidente que» pide indicativo: es.")]),
  [E("Un volante dice: «Es evidente que reciclar ayuda. Tal vez no todos lo hagan, pero conviene intentarlo». ¿Cuál frase expresa certeza?", "Es evidente que reciclar ayuda", "Usa «es evidente que» con indicativo.")],
  [E("¿«Dudo que» pide indicativo o subjuntivo?", "Subjuntivo", "Expresa una duda."),
   E("¿«Creo que» pide indicativo o subjuntivo?", "Indicativo", "Expresa una seguridad."),
   E("¿Qué modo suena más contundente en un texto persuasivo?", "El indicativo", "Presenta el hecho como seguro.")],
  ("Lee este texto de ejemplo: «El agua del embalse baja cada año. Quizás llueva más pronto, pero no lo creo. Es posible que debamos ahorrar más. Lo cierto es que usamos demasiada agua en el verano». 1) Subraya las frases de certeza y las de posibilidad. 2) Explica qué modo usa cada una. 3) Reescribe una frase de certeza para que exprese duda y una de duda para que exprese certeza.",
   "Certeza: «baja cada año», «usamos demasiada agua» (indicativo). Posibilidad: «quizás llueva», «es posible que debamos» (subjuntivo). Reescritura: «Tal vez el agua del embalse baje cada año»; «Llueve más pronto» (certeza).",
   ["clasifica certeza y posibilidad", "justifica el modo de cada una", "reescribe cambiando el grado de certeza"], ["frases clasificadas", "dos reescrituras"], ["usar indicativo con «quizás»", "no cambiar el verbo al reescribir"], "Lee tus reescrituras en voz alta; la fuerza debe cambiar."),
  "Anota tres cosas que sabes seguro de tu barrio y tres que solo crees posibles, usando el modo adecuado.",
  "Escribe dos versiones de un aviso, una con indicativo y otra con subjuntivo, y explica cómo cambia el efecto.")

L(OA19, 3,
  MAT,
  "Aprenderé a analizar la exhortación, es decir, cómo el imperativo y otras formas invitan o presionan al lector a actuar, y qué efecto produce cada una.",
  ["Reconozco los modos verbales.", "Sé qué es un texto persuasivo."],
  ["Exhortar es invitar o empujar a alguien a actuar. La forma más directa es el imperativo: «Lava tus manos», «Cierre la puerta». Según a quién se dirija, cambia la forma: tú (lava), usted (lave), ustedes (laven) y nosotros (lavemos). Las órdenes negativas usan subjuntivo: «No tires basura».",
   "Hay otras formas de exhortar. El infinitivo se usa en letreros generales: «No fumar», «Mantener limpio». La primera persona plural incluye a quien habla: «Reciclemos el papel», que suena a trabajo en equipo. Las preguntas corteses atenúan la orden: «¿Podrías bajar el volumen?». Y las fórmulas de invitación suavizan: «Te invitamos a cuidar el parque».",
   "Cada forma produce un efecto. El imperativo directo es claro y firme, pero puede sonar autoritario. La primera persona plural genera cercanía y compromiso. La pregunta cortés protege la relación con el otro. En un texto persuasivo, conviene elegir según el público: a un grupo de iguales, la inclusión; a una autoridad, la cortesía; en un peligro, la orden directa."],
  [("exhortar", "invitar o empujar a alguien a actuar"), ("imperativo", "modo que expresa órdenes, ruegos o consejos"), ("inclusivo", "que incluye a quien habla y a quien escucha"), ("cortesía", "forma amable de pedir algo")],
  [("Elegir la forma inclusiva", "Convierte «Ahorrar agua es tarea de todos» en una exhortación inclusiva.",
    ["Busco el verbo: ahorrar.", "La primera persona plural del imperativo es «ahorremos».", "Escribo: Ahorremos agua."],
    "Ahorremos agua"),
   ("Orden negativa", "¿Cómo se dice la orden negativa de «Corre» dirigida a un compañero?",
    ["La orden afirmativa es «corre».", "La negativa usa subjuntivo.", "Escribo: No corras."],
    "No corras")],
  [("Escribir «no corre» o «no corres» como orden.", "Se agrega «no» al imperativo afirmativo.", "La orden negativa usa subjuntivo: «no corras»."),
   ("Usar siempre la orden directa.", "Se piensa que es la más efectiva.", "Elige la forma según el público y el efecto.")],
  ([E("¿«Lava tus manos» es imperativo o subjuntivo?", "Imperativo", "Es una orden directa."),
    E("¿«Reciclemos el papel» incluye a quien habla?", "Sí", "La primera persona plural incluye al hablante."),
    E("¿«No fumar» usa infinitivo o imperativo?", "Infinitivo", "Es una forma general de letreros.")],
   [E("¿A quién se dirige «Cierre la puerta»: a tú o a usted?", "A usted", "«Cierre» es la forma de usted."),
    E("¿A quién se dirige «Cuiden el parque»: a ustedes o a nosotros?", "A ustedes", "«Cuiden» es la forma de ustedes."),
    E("Entre «Cuiden el parque» y «Cuidemos el parque», ¿cuál es más inclusiva?", "Cuidemos el parque", "Incluye a quien habla.")],
   [E("Escribe el imperativo de «leer» para tú.", "lee", "Es la forma de la orden afirmativa."),
    E("Escribe la orden negativa de «correr» para tú.", "no corras", "Se usa la forma del subjuntivo."),
    E("Convierte en exhortación inclusiva: «Reciclar el vidrio es tarea de todos».", "Reciclemos el vidrio", "Se usa la primera persona plural.")],
   [E("En un afiche para un curso, ¿qué genera más sentido de equipo: «Ordene su mesa» o «Ordenemos nuestra mesa»?", "Ordenemos nuestra mesa", "La primera persona plural incluye a todos."),
    E("¿Qué efecto tiene «¿Podrías bajar el volumen?» frente a «Baja el volumen»?", "Es más cortés", "La pregunta suaviza la orden.")],
   [E("¿Cuántos imperativos hay en «Lee el texto, subraya las ideas y comparte tu opinión»?", "3", "Son lee, subraya y comparte."),
    E("¿Qué forma conviene si hay un peligro urgente, como un incendio: orden directa o pregunta cortés?", "Orden directa", "Hay que actuar de inmediato, sin rodeos.")]),
  [E("Un cartel de un parque dice: «Cuidemos las plantas. No pisen el césped». ¿Cuál de las dos frases incluye a quien habla?", "Cuidemos las plantas", "Usa la primera persona plural.")],
  [E("¿La primera persona plural genera cercanía o distancia?", "Cercanía", "Incluye a quien habla y a quien escucha."),
   E("¿Qué sirve para atenuar una orden: una pregunta cortés o un grito?", "Una pregunta cortés", "Cuida la relación con el otro."),
   E("¿La orden negativa usa subjuntivo o indicativo?", "Subjuntivo", "Por ejemplo: no corras.")],
  ("Lee este afiche de ejemplo: «Reciclemos. Separen el vidrio del plástico. No mezclen la basura. ¿Podrían dejar las botellas limpias? Mantener limpio el punto de reciclaje». 1) Marca cada forma de exhortación (inclusiva, imperativo directo, orden negativa, pregunta cortés, infinitivo). 2) Escribe qué efecto tiene cada una. 3) Cambia una orden directa por una forma inclusiva.",
   "Reciclemos: inclusiva (cercanía). Separen: imperativo directo (firme). No mezclen: orden negativa con subjuntivo (prohíbe). ¿Podrían dejar...?: pregunta cortés (cuida la relación). Mantener limpio: infinitivo general. Cambio: «Separemos el vidrio del plástico».",
   ["identifica cada forma", "explica el efecto", "cambia una forma conservando el sentido"], ["formas marcadas", "efectos escritos", "oración transformada"], ["confundir la orden negativa con indicativo", "no explicar el efecto"], "Lee las dos versiones a alguien y pregúntale cuál lo motiva más."),
  "Busca un letrero de tu calle o tu colegio y anota qué forma de exhortación usa.",
  "Escribe tres versiones de la misma exhortación: directa, inclusiva y cortés, y explica cuál usarías ante tu curso.")

L(OA19, 4,
  MAT,
  "Aprenderé a seleccionar el modo verbal más adecuado según el propósito del texto, el destinatario y el efecto que quiero producir.",
  ["Reconozco indicativo, subjuntivo e imperativo.", "Sé qué efecto produce cada modo."],
  ["Antes de escribir, define tu propósito. Si quieres informar o argumentar con datos, el indicativo da firmeza. Si quieres expresar un deseo o admitir un límite, el subjuntivo ayuda. Si quieres que alguien actúe, el imperativo (o una forma exhortativa) lo pide con claridad. Y si quieres plantear una hipótesis o un consejo suave, puedes usar «si + subjuntivo imperfecto + condicional»: «Si ahorráramos agua, tendríamos más en verano».",
   "También importa el destinatario. A una autoridad se le pide con cortesía («Solicitamos que revise esta propuesta»). A compañeros se les invita en primera persona plural («Organicemos una campaña»). A una audiencia que puede dudar, se le presenta primero un hecho (indicativo) y luego se le propone una acción (imperativo).",
   "Un texto persuasivo eficaz suele combinar modos: indicativo para los datos, subjuntivo para las hipótesis o los deseos y exhortación para el cierre. Por ejemplo: «El colegio gasta mucho papel (indicativo). Si usáramos las dos caras, ahorraríamos árboles (hipótesis). Usemos las dos caras (exhortación)». Elegir el modo es elegir cómo quieres que te lea el otro."],
  [("propósito", "para qué se escribe un texto"), ("destinatario", "persona o grupo a quien va dirigido un texto"), ("hipótesis", "idea que se plantea como posible, aún no comprobada"), ("exhortativo", "que invita o pide actuar")],
  [("Elegir según el propósito", "Quieres convencer a tu curso de hacer una campaña. ¿Qué forma conviene para el cierre: «Organicemos una campaña» o «Ojalá alguien organizara una campaña»?",
    ["El propósito es mover a la acción.", "«Organicemos» invita directamente e incluye a todos.", "«Ojalá» solo expresa un deseo sin comprometer."],
    "Organicemos una campaña"),
   ("Plantear una hipótesis", "Completa: «Si ahorráramos agua, ___ (tener) más en verano».",
    ["La estructura es si + subjuntivo imperfecto + condicional.", "El verbo «tener» en condicional con nosotros es «tendríamos».", "Escribo: tendríamos."],
    "tendríamos")],
  [("Usar solo imperativo en todo el texto.", "Suena a una lista de órdenes.", "Combina datos, hipótesis y exhortación."),
   ("Elegir un modo por costumbre.", "No se piensa en el destinatario.", "Pregunta: ¿a quién escribo y qué quiero que haga?")],
  ([E("Para informar con datos, ¿conviene indicativo o imperativo?", "Indicativo", "Da firmeza a los hechos."),
    E("Para pedir que alguien actúe, ¿conviene imperativo o subjuntivo?", "Imperativo", "Es la forma directa de pedir una acción."),
    E("Para expresar un deseo, ¿conviene subjuntivo o indicativo?", "Subjuntivo", "Expresa lo que se quiere que ocurra.")],
   [E("A la directora quieres pedirle una cancha nueva. ¿Qué formulación es más adecuada: «Solicitamos que revise la propuesta» o «Revisa la propuesta»?", "Solicitamos que revise la propuesta", "Es más cortés para una autoridad."),
    E("A tus compañeros quieres invitarlos a una campaña. ¿Qué forma incluye a todos: «Organicemos una campaña» o «Organicen una campaña»?", "Organicemos una campaña", "La primera persona plural incluye a quien habla."),
    E("En «Si usáramos las dos caras, ahorraríamos árboles», ¿se plantea un hecho real o una hipótesis?", "Una hipótesis", "Usa si + subjuntivo imperfecto + condicional.")],
   [E("Completa con condicional: «Si estudiáramos más, nosotros ___ (aprobar) todas las pruebas».", "aprobaríamos", "La hipótesis termina en condicional."),
    E("Completa con exhortativo: «El curso tiene mucho papel desperdiciado. ___ (usar, nosotros) las dos caras».", "Usemos", "Cierra con una invitación inclusiva."),
    E("Completa con indicativo este dato de ejemplo: «El curso ___ (gastar) cien hojas por mes».", "gasta", "Un dato se presenta en indicativo.")],
   [E("Un texto empieza: «Ojalá tuviéramos más áreas verdes. Hay pocas plazas. Cuidemos las que existen». ¿Qué modo usa «Hay pocas plazas»?", "Indicativo", "Presenta un dato."),
    E("¿Por qué un texto que solo usa órdenes puede fallar con un lector que duda?", "Porque no presenta datos ni razones", "Sin hechos, la orden no convence.")],
   [E("Ordena según una estructura persuasiva: (1) «Usemos las dos caras». (2) «El colegio gasta mucho papel». (3) «Si usáramos las dos caras, ahorraríamos árboles». ¿Cuál va primero?", "El colegio gasta mucho papel", "Primero va el dato, luego la hipótesis y al final la invitación."),
    E("Con el mismo orden, ¿qué frase va al cierre?", "Usemos las dos caras", "Es la exhortación final.")]),
  [E("Un afiche del colegio dice: «El 70 % del papel de la sala se tira sin usar» (dato de ejemplo). Si quieres una frase que mueva a actuar, ¿qué agregas: «Ahorremos papel» o «Ojalá se tire menos papel»?", "Ahorremos papel", "Es una exhortación que sigue al dato; el deseo no pide actuar.")],
  [E("¿El propósito de un texto influye en la elección del modo?", "Sí", "Se elige el modo según lo que se quiere lograr."),
   E("¿A una autoridad conviene una petición cortés o una orden seca?", "Una petición cortés", "Cuida la relación con el otro."),
   E("¿Qué modo conviene para los datos de un texto persuasivo?", "Indicativo", "Da mucha firmeza.")],
  ("Lee este borrador de ejemplo: «Estudien más. No usen el celular. Ojalá todo mejore». 1) Explica qué modo predomina y por qué convence poco. 2) Reescribe el texto con un dato de ejemplo en indicativo, una hipótesis con «si + subjuntivo imperfecto + condicional» y una exhortación inclusiva. 3) Indica para qué destinatario escribiste.",
   "Predomina el imperativo y no hay datos. Versión: «En nuestro curso el 40 % no termina las tareas (dato de ejemplo). Si usáramos 20 minutos al día para estudiar, mejoraríamos las notas. Estudiemos juntos». Destinatario: compañeros de curso.",
   ["justifica el modo predominante", "combina los tres modos con sentido", "adecua el texto al destinatario"], ["justificación", "texto nuevo", "destinatario indicado"], ["reescribir con puras órdenes", "dato inventado sin rótulo de ejemplo"], "Pide a otra persona que diga cuál frase la convenció más."),
  "Elige una causa de tu barrio y escribe un dato en indicativo y una invitación inclusiva.",
  "Escribe una carta breve a una autoridad escolar con petición cortés y una hipótesis.")

L(OA19, 5,
  MAT,
  "Aprenderé a reescribir enunciados con distinto modo verbal y a evaluar qué efecto produce cada cambio en quien lee.",
  ["Reconozco indicativo, subjuntivo e imperativo.", "Sé qué es la exhortación."],
  ["Un mismo contenido puede decirse de varias maneras. «El agua se acaba» (indicativo) alarma con un hecho. «Ojalá no se acabe el agua» (subjuntivo) expresa un deseo. «Cuida el agua» (imperativo) pide una acción. «Si cuidáramos el agua, no se acabaría» (hipótesis) hace pensar. Cada versión cambia el efecto aunque el tema sea el mismo.",
   "Para evaluar el efecto, pregunta tres cosas: ¿qué siente el lector?, ¿qué entiende?, ¿qué haría después? El indicativo suele informar o alarmar; el subjuntivo, emocionar o hacer reflexionar; el imperativo, mover a actuar; la hipótesis, hacer ver consecuencias. Un efecto demasiado fuerte puede molestar y uno demasiado débil puede no convencer.",
   "Reescribir es un trabajo de ensayo y comparación. Escribe dos o tres versiones de la misma frase, léelas en voz alta y elige la que mejor cumple tu propósito con tu destinatario. Anota por qué la elegiste: «Elegí el imperativo inclusivo porque quiero que mis compañeros actúen conmigo»."],
  [("reescribir", "escribir de nuevo un texto cambiando la forma de decirlo"), ("efecto", "lo que produce un texto en quien lo lee"), ("alarmar", "avisar de un peligro de modo fuerte"), ("reflexionar", "pensar con calma sobre algo")],
  [("Reescribir con otro modo", "Reescribe «El río se contamina» como deseo.",
    ["El deseo se expresa con subjuntivo.", "Uso «ojalá» y el verbo en subjuntivo: contamine.", "Ojalá el río no se contamine."],
    "Ojalá el río no se contamine."),
   ("Evaluar el efecto", "¿Qué efecto principal tiene «Cuidemos el río»?",
    ["Es un imperativo inclusivo.", "Pide actuar a quien lee e incluye a quien habla.", "Mueve a la acción con cercanía."],
    "Mueve a la acción con cercanía")],
  [("Cambiar el modo y perder el sentido.", "Se reescribe sin releer.", "Comprueba que el tema se mantenga."),
   ("Elegir siempre la versión más fuerte.", "Se cree que la alarma convence siempre.", "Elige según el destinatario y el propósito.")],
  ([E("¿«El agua se acaba» está en indicativo o en subjuntivo?", "Indicativo", "Presenta un hecho."),
    E("¿«Ojalá no se acabe el agua» expresa un deseo o una orden?", "Un deseo", "Está en subjuntivo."),
    E("¿«Cuida el agua» expresa una orden o una duda?", "Una orden", "Está en imperativo.")],
   [E("¿Qué efecto principal tiene «El agua se acaba»: alarmar con un hecho o expresar un deseo?", "Alarmar con un hecho", "Está en indicativo."),
    E("¿Qué efecto principal tiene «Si cuidáramos el agua, no se acabaría»: hacer ver consecuencias o dar una orden?", "Hacer ver consecuencias", "Es una hipótesis."),
    E("¿Qué efecto principal tiene «Cuidemos el río»: mover a la acción con cercanía o expresar un deseo?", "Mover a la acción con cercanía", "Es una exhortación inclusiva.")],
   [E("Reescribe como deseo: «La plaza se llena de basura».", "Ojalá la plaza no se llene de basura.", "El deseo usa subjuntivo con «ojalá»."),
    E("Reescribe como hipótesis: «No reciclamos y la basura crece».", "Si recicláramos, la basura no crecería.", "Estructura de si + subjuntivo imperfecto + condicional."),
    E("Reescribe como invitación inclusiva: «La playa está sucia».", "Limpiemos la playa", "Convierte el dato en una acción compartida.")],
   [E("Entre «Ojalá limpien la playa» y «Limpiemos la playa», ¿cuál compromete más a quien habla?", "Limpiemos la playa", "Incluye a quien habla en la acción."),
    E("Un compañero dice que «El agua se acaba» es mejor siempre porque alarma. ¿Tiene razón?", "No", "Según el destinatario, el efecto fuerte puede molestar o paralizar.")],
   [E("Un afiche escolar dice: «¡El colegio se derrumbará si no ahorran luz!». ¿Qué problema tiene el efecto?", "Es exagerado y pierde credibilidad", "Un efecto desmedido molesta al lector."),
    E("Reescribe con cortesía para una autoridad: «Limpia la plaza».", "¿Podría limpiar la plaza, por favor?", "La pregunta cortés atenúa la orden.")]),
  [E("Un cartel de un colegio dice: «La sala se ensucia cada día». Quieren que motive a la acción con cercanía. ¿Cuál reescritura sirve: «Mantengamos limpia la sala» o «Ojalá la sala no se ensucie»?", "Mantengamos limpia la sala", "Es exhortación inclusiva.")],
  [E("¿Reescribir cambia el tema o la forma de decirlo?", "La forma de decirlo", "El tema se mantiene."),
   E("¿Qué pregunta ayuda a evaluar el efecto: ¿qué siente el lector? o ¿cuántas palabras hay?", "¿Qué siente el lector?", "El efecto se mide en el lector."),
   E("¿Conviene elegir el efecto más fuerte siempre?", "No", "Depende del destinatario y el propósito.")],
  ("Parte de esta frase de ejemplo: «La luz del colegio se gasta». 1) Escribe cuatro versiones: indicativo alarmante, deseo con subjuntivo, hipótesis y exhortación inclusiva. 2) Explica el efecto de cada una en una línea. 3) Elige la mejor para un cartel en el pasillo y justifica.",
   "Indicativo: «La luz del colegio se gasta sin parar». Deseo: «Ojalá la luz no se gaste tanto». Hipótesis: «Si apagáramos las luces, gastaríamos menos». Exhortación: «Apaguemos las luces al salir». Mejor: la exhortación, porque en un pasillo se necesita una acción corta que incluya a todos.",
   ["escribe las cuatro versiones", "explica el efecto de cada una", "justifica la elección"], ["cuatro versiones", "cuatro efectos", "elección justificada"], ["no cambiar de modo", "no relacionar la elección con el destinatario"], "Pregunta a una persona cuál versión la haría actuar y por qué."),
  "Toma un titular de noticia y reescríbelo en deseo y en exhortación.",
  "Escribe tres versiones de un aviso para tu casa y elige la mejor según quien lo lea.")

L(OA19, 6,
  MAT,
  "Aprenderé a integrar los tres modos verbales en un texto persuasivo breve, eligiendo cada uno por su efecto.",
  ["Reconozco y selecciono modos verbales.", "Sé estructurar un texto persuasivo."],
  ["Un texto persuasivo breve tiene tres partes: un dato o afirmación, una razón o hipótesis y una invitación a actuar. Cada parte pide un modo distinto. El dato va en indicativo, la razón o hipótesis en subjuntivo (con «si» o con expresiones como «es posible que»), y la invitación en imperativo o exhortativo.",
   "Por ejemplo: «En el patio hay tres basureros, pero casi nadie los usa (indicativo). Si los usáramos mejor, el patio estaría más limpio (hipótesis). Cuidemos nuestro patio (exhortación)». Para que funcione, el tema debe ser el mismo en las tres partes, y los modos deben seguir un orden lógico.",
   "Al revisar, verifica que: cada modo esté bien conjugado, el dato sea cierto o esté rotulado como ejemplo, la hipótesis sea razonable y la invitación se dirija al destinatario correcto. Evita mezclar certezas con dudas sobre el mismo hecho y no uses más de una exhortación seguida. Un texto breve y claro convence más que uno largo y repetitivo."],
  [("persuasivo", "que busca convencer al lector"), ("dato", "información concreta que apoya una idea"), ("hipótesis", "idea posible que se plantea para pensar consecuencias"), ("invitación", "frase que pide al lector actuar")],
  [("Armar un texto en tres partes", "Completa con los tres modos: «Mi curso tiene un reloj de pared roto. Si lo ___ (arreglar), sabríamos la hora. ___ (Pedir, nosotros) ayuda».",
    ["La segunda frase es una hipótesis: si + subjuntivo imperfecto.", "El verbo es «arreglar» y la forma, «arregláramos».", "La invitación inclusiva es «Pidamos ayuda»."],
    "arregláramos; Pidamos"),
   ("Revisar la combinación de modos", "¿Qué problema hay en «Es seguro que lloverá, pero quizás no llueva»?",
    ["La primera parte afirma una certeza.", "La segunda duda del mismo hecho.", "Se contradicen."],
    "Mezcla certeza y duda sobre el mismo hecho")],
  [("Mezclar certeza y duda sobre el mismo hecho.", "Se dice algo y se desdice sin razón.", "Define si el hecho es seguro o posible y usa un solo modo."),
   ("Llenar el texto de órdenes.", "Se piensa que más órdenes convencen más.", "Usa una invitación final, bien preparada con datos.")],
  ([E("¿En qué parte del texto persuasivo va el dato: al inicio o al cierre?", "Al inicio", "Primero va el dato, luego la razón y al final la invitación."),
    E("¿Qué modo usa el dato: indicativo o imperativo?", "Indicativo", "Presenta un hecho."),
    E("¿Qué modo usa la invitación final: indicativo o imperativo/exhortativo?", "Imperativo o exhortativo", "Pide al lector actuar.")],
   [E("¿Qué parte del texto usa «si + subjuntivo imperfecto»: el dato o la hipótesis?", "La hipótesis", "Plantea una situación posible."),
    E("¿Qué problema tiene «Es seguro que lloverá, pero quizás no llueva»?", "Se contradice", "Afirma y duda del mismo hecho."),
    E("¿Cuántas exhortaciones seguidas conviene usar?", "Una", "Más de una seguida cansa al lector.")],
   [E("Completa la hipótesis: «Si el curso ___ (ordenar) la sala, trabajaríamos mejor».", "ordenara", "Usa subjuntivo imperfecto después de «si»."),
    E("Completa el dato en indicativo: «El patio ___ (tener) tres basureros, pero ninguno se usa», dato de ejemplo.", "tiene", "Un dato se presenta en indicativo."),
    E("Completa la invitación inclusiva: «___ (cuidar, nosotros) el patio».", "Cuidemos", "Primera persona plural del imperativo.")],
   [E("Un compañero escribe: «Ojalá reciclen. Reciclen. Reciclen». ¿Qué defecto tiene?", "Repite la orden sin datos", "Una orden repetida no convence."),
    E("¿Qué pasa si el dato no es cierto: el texto pierde credibilidad o se hace más corto?", "Pierde credibilidad", "La persuasión depende de datos confiables.")],
   [E("Ordena las partes: (1) «Cuidemos el parque». (2) «El parque tiene mucha basura». (3) «Si lo limpiáramos, sería más agradable». ¿Cuál va en segundo lugar?", "Si lo limpiáramos, sería más agradable", "Dato, hipótesis, invitación."),
    E("¿Qué modo tiene «tiene» en «El parque tiene mucha basura»?", "Indicativo", "Es un dato.")]),
  [E("Un volante de un vecino dice: «La calle tiene 5 luminarias y 3 no funcionan» (dato de ejemplo). ¿Qué modo tiene «funcionan»?", "Indicativo", "Presenta un hecho.")],
  [E("¿Un texto persuasivo breve tiene dato, hipótesis e invitación?", "Sí", "Esas son sus tres partes."),
   E("¿La hipótesis lleva indicativo o subjuntivo?", "Subjuntivo", "Plantea algo posible."),
   E("¿El destinatario influye en el modo de la invitación?", "Sí", "A una autoridad, cortesía; a compañeros, inclusión.")],
  ("Escribe un texto persuasivo de tres a cinco oraciones sobre un problema de tu escuela o barrio (por ejemplo, ruido en los recreos o basura en una plaza). Usa un dato de ejemplo en indicativo, una hipótesis con «si + subjuntivo imperfecto + condicional» y una exhortación inclusiva. Rotula cada parte y escribe qué modo usaste.",
   "Ejemplo: «En el recreo hay mucho ruido en el pasillo (indicativo, dato de ejemplo). Si habláramos más bajo, todos descansaríamos (hipótesis). Cuidemos nuestros recreos (exhortación)». Modos: indicativo, subjuntivo imperfecto y condicional, imperativo inclusivo.",
   ["incluye los tres modos", "mantiene el tema", "rotula el dato como ejemplo"], ["texto de tres a cinco oraciones", "modos rotulados"], ["mezclar certeza y duda sobre el mismo hecho", "terminar con varias órdenes"], "Pide a alguien que lea el texto y diga qué haría después de leerlo."),
  "Escribe una versión de tu texto dirigida a una autoridad y otra dirigida a tus compañeros.",
  "Intercambia tu texto con alguien y marquen mutuamente los modos y los efectos.")
